#include "hado_runtime.h"
#include <errno.h>
#include <gc.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Guest entry generated by Cranelift emit. Defined in the guest object. */
int32_t hado_entry(void);

static int print_failed;

static void note_print_failure(void) {
  /* Why not exit() here: raise uses hado_abort_error, and main still has to
     observe a trailing fflush(stdout) failure. */
  if (print_failed) {
    return;
  }
  print_failed = 1;
  fprintf(stderr, "hado: print failed: %s\n", strerror(errno));
}

static void check_stdout(int wrote) {
  if (!wrote || ferror(stdout) || fflush(stdout) == EOF) {
    note_print_failure();
  }
}

void *hado_alloc(size_t size) { return GC_malloc(size); }

void hado_print_int(int64_t v) {
  check_stdout(printf("%lld\n", (long long)v) >= 0);
}

int main(void) {
  signal(SIGPIPE, SIG_IGN);
  GC_INIT();
  int32_t code = hado_entry();
  check_stdout(1);
  return print_failed ? 1 : code;
}

int64_t hado_string_length(const HadoString *string) {
  int64_t count = 0;
  for (size_t i = 0; i < string->length; ++i) {
    if ((string->bytes[i] & 0xc0) != 0x80) {
      if (count == INT64_MAX) abort();
      ++count;
    }
  }
  return count;
}

HadoString *hado_string_concat(const HadoString *left, const HadoString *right) {
  if (left->length > SIZE_MAX - right->length) abort();
  size_t length = left->length + right->length;
  if (length > SIZE_MAX - sizeof(HadoString)) abort();
  HadoString *result = hado_alloc(sizeof(HadoString) + length);
  if (result == NULL) abort();
  result->length = length;
  memcpy(result->bytes, left->bytes, left->length);
  memcpy(result->bytes + left->length, right->bytes, right->length);
  return result;
}

int64_t hado_string_compare(const HadoString *left, const HadoString *right) {
  size_t common = left->length < right->length ? left->length : right->length;
  int order = memcmp(left->bytes, right->bytes, common);
  if (order != 0) return order < 0 ? -1 : 1;
  return (left->length > right->length) - (left->length < right->length);
}

static size_t string_byte_offset(const HadoString *string, int64_t index) {
  size_t offset = 0;
  while (index > 0) {
    ++offset;
    while (offset < string->length && (string->bytes[offset] & 0xc0) == 0x80) {
      ++offset;
    }
    --index;
  }
  return offset;
}

HadoString *hado_string_slice(const HadoString *string, int64_t start, int64_t end) {
  size_t first = string_byte_offset(string, start);
  size_t length = string_byte_offset(string, end) - first;
  if (length > SIZE_MAX - sizeof(HadoString)) abort();
  HadoString *result = hado_alloc(sizeof(HadoString) + length);
  if (result == NULL) abort();
  result->length = length;
  memcpy(result->bytes, string->bytes + first, length);
  return result;
}

uint32_t hado_string_get(const HadoString *string, int64_t index) {
  size_t offset = string_byte_offset(string, index);
  uint32_t scalar = string->bytes[offset++];
  if (scalar < 0x80) return scalar;
  scalar &= scalar < 0xe0 ? 0x1f : scalar < 0xf0 ? 0x0f : 0x07;
  while (offset < string->length && (string->bytes[offset] & 0xc0) == 0x80) {
    scalar = (scalar << 6) | (string->bytes[offset++] & 0x3f);
  }
  return scalar;
}

int64_t hado_string_find(const HadoString *string, const HadoString *separator, int64_t from) {
  size_t offset = string_byte_offset(string, from);
  for (; offset < string->length; ++offset) {
    if ((string->bytes[offset] & 0xc0) == 0x80) continue;
    if (separator->length > string->length - offset) return -1;
    if (memcmp(string->bytes + offset, separator->bytes, separator->length) == 0) return from;
    ++from;
  }
  return -1;
}

void hado_print_string(const HadoString *string) {
  int wrote = fwrite(string->bytes, 1, string->length, stdout) == string->length
              && fputc('\n', stdout) != EOF;
  check_stdout(wrote);
}

static size_t encode_char(uint32_t value, unsigned char bytes[4]) {
  size_t length;
  if (value <= 0x7f) {
    bytes[0] = value;
    length = 1;
  } else if (value <= 0x7ff) {
    bytes[0] = 0xc0 | (value >> 6);
    bytes[1] = 0x80 | (value & 0x3f);
    length = 2;
  } else if (value <= 0xffff && !(value >= 0xd800 && value <= 0xdfff)) {
    bytes[0] = 0xe0 | (value >> 12);
    bytes[1] = 0x80 | ((value >> 6) & 0x3f);
    bytes[2] = 0x80 | (value & 0x3f);
    length = 3;
  } else if (value >= 0x10000 && value <= 0x10ffff) {
    bytes[0] = 0xf0 | (value >> 18);
    bytes[1] = 0x80 | ((value >> 12) & 0x3f);
    bytes[2] = 0x80 | ((value >> 6) & 0x3f);
    bytes[3] = 0x80 | (value & 0x3f);
    length = 4;
  } else {
    abort();
  }
  return length;
}

void hado_print_char(uint32_t value) {
  unsigned char bytes[4];
  size_t length = encode_char(value, bytes);
  int wrote = fwrite(bytes, 1, length, stdout) == length && fputc('\n', stdout) != EOF;
  check_stdout(wrote);
}

void hado_print_float(double value) {
  check_stdout(printf("%.17g\n", value) >= 0);
}

HadoString *hado_int_to_string(int64_t value) {
  char buffer[32];
  int length = snprintf(buffer, sizeof(buffer), "%lld", (long long)value);
  if (length < 0 || (size_t)length >= sizeof(buffer)) abort();
  HadoString *result = hado_alloc(sizeof(HadoString) + (size_t)length);
  if (result == NULL) abort();
  result->length = (size_t)length;
  memcpy(result->bytes, buffer, result->length);
  return result;
}

HadoString *hado_float_to_string(double value) {
  char buffer[32];
  int length = snprintf(buffer, sizeof(buffer), "%.17g", value);
  if (length < 0 || (size_t)length >= sizeof(buffer)) abort();
  HadoString *result = hado_alloc(sizeof(HadoString) + (size_t)length);
  if (result == NULL) abort();
  result->length = (size_t)length;
  memcpy(result->bytes, buffer, result->length);
  return result;
}

HadoString *hado_char_to_string(uint32_t value) {
  unsigned char bytes[4];
  size_t length = encode_char(value, bytes);
  HadoString *result = hado_alloc(sizeof(HadoString) + length);
  if (result == NULL) abort();
  result->length = length;
  memcpy(result->bytes, bytes, length);
  return result;
}

void hado_print_error_string(const HadoString *string) {
  fwrite(string->bytes, 1, string->length, stderr);
  fputc('\n', stderr);
  fflush(stderr);
}

void hado_abort_error(const HadoString *string) {
  hado_print_error_string(string);
  exit(1);
}

/* Bytes and String share the HadoString layout. Bytes.length is the byte
   count, String.length the scalar count; RFC 3629's well-formedness is what
   Bytes.to_string validates before the identity conversion runs. */
int64_t hado_bytes_length(const HadoString *bytes) {
  if (bytes->length > INT64_MAX) abort();
  return (int64_t)bytes->length;
}

int64_t hado_bytes_get(const HadoString *bytes, int64_t index) {
  return (int64_t)bytes->bytes[index];
}

static int well_formed_utf8(const unsigned char *bytes, size_t length) {
  size_t i = 0;
  while (i < length) {
    unsigned char first = bytes[i];
    size_t continuation;
    uint32_t value;
    uint32_t minimum;
    if (first < 0x80) {
      ++i;
      continue;
    } else if ((first & 0xe0) == 0xc0) {
      continuation = 1;
      value = first & 0x1f;
      minimum = 0x80;
    } else if ((first & 0xf0) == 0xe0) {
      continuation = 2;
      value = first & 0x0f;
      minimum = 0x800;
    } else if ((first & 0xf8) == 0xf0) {
      continuation = 3;
      value = first & 0x07;
      minimum = 0x10000;
    } else {
      return 0;
    }
    if (i + continuation >= length) return 0;
    for (size_t offset = 1; offset <= continuation; ++offset) {
      unsigned char next = bytes[i + offset];
      if ((next & 0xc0) != 0x80) return 0;
      value = (value << 6) | (next & 0x3f);
    }
    if (value < minimum || value > 0x10ffff || (value >= 0xd800 && value <= 0xdfff)) return 0;
    i += continuation + 1;
  }
  return 1;
}

int8_t hado_bytes_is_utf8(const HadoString *bytes) {
  return well_formed_utf8(bytes->bytes, bytes->length) ? 1 : 0;
}

HadoString *hado_bytes_display(const HadoString *bytes) {
  static const char prefix[] = "Bytes.of_list [";
  size_t prefix_length = sizeof(prefix) - 1;
  if (bytes->length > (SIZE_MAX - sizeof(HadoString) - prefix_length - 1) / 5) abort();
  size_t capacity = prefix_length + bytes->length * 5 + 1;
  HadoString *result = hado_alloc(sizeof(HadoString) + capacity);
  if (result == NULL) abort();
  size_t length = 0;
  memcpy(result->bytes, prefix, prefix_length);
  length += prefix_length;
  for (size_t i = 0; i < bytes->length; ++i) {
    if (i > 0) {
      result->bytes[length++] = ',';
      result->bytes[length++] = ' ';
    }
    unsigned value = bytes->bytes[i];
    if (value >= 100) {
      result->bytes[length++] = (unsigned char)('0' + value / 100);
      value %= 100;
      result->bytes[length++] = (unsigned char)('0' + value / 10);
      result->bytes[length++] = (unsigned char)('0' + value % 10);
    } else if (value >= 10) {
      result->bytes[length++] = (unsigned char)('0' + value / 10);
      result->bytes[length++] = (unsigned char)('0' + value % 10);
    } else {
      result->bytes[length++] = (unsigned char)('0' + value);
    }
  }
  result->bytes[length++] = ']';
  result->length = length;
  return result;
}

HadoString *hado_bytes_of_string(const HadoString *value) {
  return (HadoString *)value;
}

HadoString *hado_bytes_to_string_unchecked(const HadoString *bytes) {
  return (HadoString *)bytes;
}

HadoString *hado_bytes_alloc(int64_t length) {
  if (length < 0 || (uint64_t)length > SIZE_MAX - sizeof(HadoString)) abort();
  HadoString *result = hado_alloc(sizeof(HadoString) + (size_t)length);
  if (result == NULL) abort();
  result->length = (size_t)length;
  return result;
}

/* Only Bytes.of_list calls this, on a buffer that has not escaped and is
   filled in one pass; the byte is range-checked before the build starts. */
HadoString *hado_bytes_fill_unchecked(HadoString *bytes, int64_t index, int64_t value) {
  bytes->bytes[index] = (unsigned char)value;
  return bytes;
}
